/*
 * MERGEN Bilge offline CodeMirror 5 compatibility build.
 *
 * The application uses CodeMirror as a read-only, fully rendered code viewer.
 * This local build deliberately implements the API surface used by
 * www/js/codemirror-manager.js without viewport virtualization, so
 * viewportMargin: Infinity renders every line and works without internet/CDN.
 */
(function (window, document) {
  'use strict';

  if (window.CodeMirror && typeof window.CodeMirror.fromTextArea === 'function') {
    return;
  }

  function createElement(tagName, className) {
    var element = document.createElement(tagName);
    if (className) element.className = className;
    return element;
  }

  function removeChildren(element) {
    while (element.firstChild) element.removeChild(element.firstChild);
  }

  function normalizeSize(value) {
    if (value == null) return '';
    return typeof value === 'number' ? value + 'px' : String(value);
  }

  function OfflineCodeMirror(textarea, options) {
    this._textarea = textarea;
    this._options = options || {};
    this._handlers = Object.create(null);
    this._value = textarea && textarea.value != null ? String(textarea.value) : '';

    this._wrapper = createElement('div', 'CodeMirror cm-s-' + (this._options.theme || 'default'));
    if (this._options.lineWrapping) this._wrapper.className += ' CodeMirror-wrap';
    this._wrapper.CodeMirror = this;

    this._scroll = createElement('div', 'CodeMirror-scroll');
    this._sizer = createElement('div', 'CodeMirror-sizer');
    this._lines = createElement('div', 'CodeMirror-lines');
    this._code = createElement('div', 'CodeMirror-code');

    this._lines.appendChild(this._code);
    this._sizer.appendChild(this._lines);
    this._scroll.appendChild(this._sizer);
    this._wrapper.appendChild(this._scroll);

    if (textarea) {
      textarea.style.display = 'none';
      if (textarea.parentNode) {
        textarea.parentNode.insertBefore(this._wrapper, textarea.nextSibling);
      }
    }

    this._bindDomEvents();
    this.refresh();
  }

  OfflineCodeMirror.prototype._bindDomEvents = function () {
    var self = this;
    this._wrapper.addEventListener('click', function (event) {
      var target = event.target;
      if (!target || !target.getAttribute) return;
      var line = target.getAttribute('data-cm-line');
      var gutter = target.getAttribute('data-cm-gutter');
      if (line == null || gutter == null) return;
      self._emit('gutterClick', self, Number(line), gutter, event);
    });
  };

  OfflineCodeMirror.prototype._emit = function (eventName) {
    var handlers = this._handlers[eventName] || [];
    var args = Array.prototype.slice.call(arguments, 1);
    handlers.slice().forEach(function (handler) {
      handler.apply(null, args);
    });
  };

  OfflineCodeMirror.prototype.on = function (eventName, handler) {
    if (typeof handler !== 'function') return this;
    if (!this._handlers[eventName]) this._handlers[eventName] = [];
    this._handlers[eventName].push(handler);
    return this;
  };

  OfflineCodeMirror.prototype.off = function (eventName, handler) {
    var handlers = this._handlers[eventName];
    if (!handlers) return this;
    this._handlers[eventName] = handlers.filter(function (item) {
      return item !== handler;
    });
    return this;
  };

  OfflineCodeMirror.prototype._render = function () {
    var self = this;
    var lines = this._value.split('\n');
    if (lines.length === 0) lines = [''];

    removeChildren(this._code);

    lines.forEach(function (lineText, lineIndex) {
      var row = createElement('div', 'CodeMirror-line-row');

      if (self._options.lineNumbers) {
        var gutter = createElement('span', 'CodeMirror-linenumber CodeMirror-gutter-elt');
        gutter.textContent = String(lineIndex + 1);
        gutter.setAttribute('data-cm-line', String(lineIndex));
        gutter.setAttribute('data-cm-gutter', 'CodeMirror-linenumbers');
        row.appendChild(gutter);
      }

      if (self._options.foldGutter) {
        var fold = createElement('span', 'CodeMirror-foldgutter-open CodeMirror-gutter-elt');
        fold.setAttribute('data-cm-line', String(lineIndex));
        fold.setAttribute('data-cm-gutter', 'CodeMirror-foldgutter');
        row.appendChild(fold);
      }

      var pre = createElement('pre', 'CodeMirror-line');
      pre.setAttribute('role', 'presentation');
      pre.textContent = lineText || ' ';
      row.appendChild(pre);
      self._code.appendChild(row);
    });
  };

  OfflineCodeMirror.prototype.refresh = function () {
    this._render();
    return this;
  };

  OfflineCodeMirror.prototype.setSize = function (width, height) {
    var normalizedWidth = normalizeSize(width);
    var normalizedHeight = normalizeSize(height);
    if (normalizedWidth) this._wrapper.style.width = normalizedWidth;
    if (normalizedHeight) this._wrapper.style.height = normalizedHeight;
    return this;
  };

  OfflineCodeMirror.prototype.getValue = function () {
    return this._value;
  };

  OfflineCodeMirror.prototype.setValue = function (value) {
    this._value = value == null ? '' : String(value);
    if (this._textarea) this._textarea.value = this._value;
    this.refresh();
    this._emit('change', this);
    return this;
  };

  OfflineCodeMirror.prototype.lineCount = function () {
    return this._value === '' ? 1 : this._value.split('\n').length;
  };

  OfflineCodeMirror.prototype.getWrapperElement = function () {
    return this._wrapper;
  };

  OfflineCodeMirror.prototype.getTextArea = function () {
    return this._textarea;
  };

  OfflineCodeMirror.prototype.getOption = function (name) {
    return this._options[name];
  };

  OfflineCodeMirror.prototype.setOption = function (name, value) {
    this._options[name] = value;
    if (name === 'theme') {
      this._wrapper.className = this._wrapper.className.replace(/\bcm-s-\S+/g, '').trim();
      this._wrapper.className += ' cm-s-' + value;
    }
    this.refresh();
    return this;
  };

  OfflineCodeMirror.prototype.operation = function (callback) {
    return typeof callback === 'function' ? callback() : undefined;
  };

  OfflineCodeMirror.prototype.focus = function () {
    return this;
  };

  OfflineCodeMirror.prototype.foldCode = function () {
    return this;
  };

  OfflineCodeMirror.prototype.toTextArea = function () {
    if (this._textarea) this._textarea.style.display = '';
    if (this._wrapper.parentNode) this._wrapper.parentNode.removeChild(this._wrapper);
  };

  function CodeMirror(place, options) {
    var textarea = createElement('textarea');
    var editor = new OfflineCodeMirror(textarea, options || {});
    if (typeof place === 'function') place(editor.getWrapperElement());
    else if (place && place.appendChild) place.appendChild(editor.getWrapperElement());
    return editor;
  }

  CodeMirror.fromTextArea = function (textarea, options) {
    return new OfflineCodeMirror(textarea, options || {});
  };
  CodeMirror.defineMode = function () {};
  CodeMirror.defineMIME = function () {};
  CodeMirror.commands = Object.create(null);
  CodeMirror.modes = Object.create(null);
  CodeMirror.mimeModes = Object.create(null);
  CodeMirror.Pos = function (line, ch) { return { line: line, ch: ch }; };
  CodeMirror.signal = function (target, eventName) {
    if (target && typeof target._emit === 'function') {
      var args = Array.prototype.slice.call(arguments, 2);
      target._emit.apply(target, [eventName].concat(args));
    }
  };
  CodeMirror.version = '5.65.21-mergen-offline-compat';

  window.CodeMirror = CodeMirror;
})(window, document);
